/// <summary>
/// Helper class for user security and warehouse restrictions on Purchase Orders.
/// </summary>
public class METPOWarehouseRestrictionHelper
{

}

Method.Source:
/// <summary>
/// Retrieves the list of allowed warehouses for the current user and company based on PO receipts restriction.
/// </summary>
/// <param name = "_userId">UserId, default is current user</param>
/// <param name = "_company">CompanyId, default is current company</param>
/// <returns>Container of allowed warehouse IDs</returns>
public static container getAllowedWarehouses(UserId _userId = curUserId(), DataAreaId _company = curExt())
{
    SysGlobalObjectCache sgoc = classfactory.globalObjectCache();
    container cacheKey = [_userId, _company];
    container cachedResult = sgoc.find(classStr(METPOWarehouseRestrictionHelper), cacheKey);

    if (cachedResult == conNull())
    {
        METUserSecurityWarehouseList      warehouseList;
        METUserSecurityGroupList          securityGroupList;
        METUserSecurityWarehouseList      restrictedWarehouseList;
        METUserSecurityGroupList          restrictedSecurityGroupList;
        container                         allowedWarehouses;

        // Retrieve all allowed warehouses in a single optimized SQL query using NOTEXISTS join.
        // This filters out any warehouse that has RestrictPurchaseOrders = Yes in any of the user's groups.
        while select InventLocationId from warehouseList
            group by InventLocationId
            where warehouseList.Company == _company
            exists join securityGroupList
                where securityGroupList.UserSecurityGroupId == warehouseList.UserSecurityGroupId
                   && securityGroupList.UserId == _userId
            notexists join restrictedWarehouseList
                where restrictedWarehouseList.InventLocationId == warehouseList.InventLocationId
                   && restrictedWarehouseList.Company == _company
                   && restrictedWarehouseList.RestrictPurchaseOrders == NoYes::Yes
            exists join restrictedSecurityGroupList
                where restrictedSecurityGroupList.UserSecurityGroupId == restrictedWarehouseList.UserSecurityGroupId
                   && restrictedSecurityGroupList.UserId == _userId
        {
            allowedWarehouses += warehouseList.InventLocationId;
        }

        cachedResult = [allowedWarehouses];
        sgoc.insert(classStr(METPOWarehouseRestrictionHelper), cacheKey, cachedResult);
    }

    return conPeek(cachedResult, 1);
}

/// <summary>
/// Adds a query range using query expressions on a placeholder field to restrict the datasource to only allowed warehouses for PO.
/// </summary>
/// <param name = "_purchTableDS">PurchTable QueryBuildDataSource</param>
public static void addWarehouseRestrictionRange(QueryBuildDataSource _purchTableDS)
{
    if (METSecurityPolicyHelper::isRoleActiveForCurrentUser(roleStr(METInventLocationPolicyRole)))
    {
        container allowedWarehouses = METPOWarehouseRestrictionHelper::getAllowedWarehouses();
        int len = conLen(allowedWarehouses);
        str rangeValue;

        for (int i = 1; i <= len; i++)
        {
            InventLocationId inventLocationId = conPeek(allowedWarehouses, i);

            if (rangeValue)
            {
                rangeValue += strFmt(' || (%1 == "%2")', fieldStr(PurchTable, InventLocationId), inventLocationId);
            }
            else
            {
                rangeValue = strFmt('(%1 == "%2")', fieldStr(PurchTable, InventLocationId), inventLocationId);
            }
        }

        if (!rangeValue)
        {
            rangeValue = strFmt('(%1 == "%2")', fieldStr(PurchTable, InventLocationId), 'NoAccess');
        }

        QueryBuildRange qbr = _purchTableDS.addRange(fieldNum(PurchTable, DataAreaId));
        qbr.status(RangeStatus::Locked);
        qbr.value(strFmt('(%1)', rangeValue));
    }
}
